  const form=document.querySelector('#sales-return-form');if(!form)return;const lineBody=document.querySelector('#sales-return-lines'),products=new Map();
  async function loadLocations(){const r=await api('/selectors/locations');document.querySelector('#sales-return-location-options').innerHTML=r.items.map(x=>`<option value="${esc(x.code)}">${esc(x.name)}</option>`).join('')}
  async function loadCustomers(q=''){const r=await api(`/selectors/parties?kind=customer&q=${encodeURIComponent(q)}`);document.querySelector('#sales-return-customer-options').innerHTML=r.items.map(x=>`<option value="${esc(x.party_code)}">${esc(x.name)}</option>`).join('')}
  const field=name=>form.querySelector(`[name="${name}"]`),customerField=field('customer_code');
  async function loadInvoices(){const code=customerField.value.trim();if(!code){document.querySelector('#sales-return-invoice-options').innerHTML='';return}const r=await api(`/selectors/sales-invoices?customer_code=${encodeURIComponent(code)}`);document.querySelector('#sales-return-invoice-options').innerHTML=r.items.map(x=>`<option value="${esc(x.document_no)}">${esc(date(x.occurred_at))} — ${esc(money(x.total_amount))}</option>`).join('')}
  async function loadProducts(q=''){const r=await api(`/selectors/products?q=${encodeURIComponent(q)}`);r.items.forEach(x=>products.set(x.sku,x));document.querySelector('#sales-return-product-options').innerHTML=r.items.map(x=>`<option value="${esc(x.sku)}">${esc(x.name)} — ${esc(x.uom||'UOM review required')}</option>`).join('')}
  function bindLines(){document.querySelectorAll('.remove-sales-return-line').forEach(b=>b.onclick=()=>{if(document.querySelectorAll('.sales-return-line').length>1)b.closest('tr').remove()});document.querySelectorAll('.sales-return-line [name=sku]').forEach(input=>{input.oninput=()=>{clearTimeout(input.searchTimer);input.searchTimer=setTimeout(()=>loadProducts(input.value),250)};input.onchange=()=>{const p=products.get(input.value.trim()),row=input.closest('tr');if(p){row.querySelector('[name=uom]').value=p.uom||'';if(p.selling_price_evidence!=null)row.querySelector('[name=unit_price]').value=p.selling_price_evidence;if(p.purchase_price_evidence!=null)row.querySelector('[name=unit_cost]').value=p.purchase_price_evidence}}})}
